// Title: Apply a custom currency number format to cells generated by smart markers using Aspose.Cells for .NET
// Common Searches: Aspose.Cells C# apply custom number format to smart marker output | Set currency format for column populated by WorkbookDesigner smart markers | Formatting price cells after processing smart markers in Aspose.Cells .NET | Create and assign a custom style to rows generated by smart markers in Excel | How to use WorkbookDesigner to format numeric data as currency in C#
// Tags: WorkbookDesigner custom number format | Aspose.Cells currency style application | smart markers apply style C# | Excel currency formatting Aspose.Cells | custom style for generated rows Aspose

using System;
using System.Data;
using System.IO;
using Aspose.Cells;

// The example loads an Excel template with smart markers, binds a DataTable of product names and prices using WorkbookDesigner, processes the markers, creates a style with the custom currency format "$#,##0.00", and applies this style to the price cells in column B for all generated rows before saving the workbook.
class Program
{
    static void Main()
    {
        try
        {
            const string templatePath = "SmartMarkerTemplate.xlsx";
            const string outputPath = "SmartMarkerOutput.xlsx";

            // Verify that the template file exists to avoid FileNotFoundException
            if (!File.Exists(templatePath))
                throw new FileNotFoundException($"Template file not found: {templatePath}");

            // Load the workbook template that contains smart markers
            Workbook workbook = new Workbook(templatePath);

            // Prepare a data source with currency values
            DataTable dt = new DataTable("Products");
            dt.Columns.Add("Name", typeof(string));
            dt.Columns.Add("Price", typeof(double));
            dt.Rows.Add("Apple", 1.23);
            dt.Rows.Add("Banana", 0.56);
            dt.Rows.Add("Cherry", 2.78);

            // Process the smart markers using WorkbookDesigner (alternative to SmartMarkerProcessor)
            WorkbookDesigner designer = new WorkbookDesigner(workbook);
            designer.SetDataSource(dt);
            designer.Process();

            // Create a custom number format for currency (e.g., $1,234.56)
            Style currencyStyle = workbook.CreateStyle();
            currencyStyle.Custom = "$#,##0.00";

            // Apply the custom format to the cells that received the price values
            // Assuming the smart marker placed prices in column B starting from row 2
            Worksheet sheet = workbook.Worksheets[0];
            int startRow = 1; // zero‑based index for row 2
            int endRow = startRow + dt.Rows.Count - 1;
            for (int row = startRow; row <= endRow; row++)
            {
                Cell priceCell = sheet.Cells[row, 1]; // column B (index 1)
                priceCell.SetStyle(currencyStyle);
            }

            // Save the workbook with the applied formatting
            workbook.Save(outputPath);
            Console.WriteLine($"Workbook saved successfully to '{outputPath}'.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
